import { createContext, useContext, type ReactNode } from "react";
import { MotionProvider, type MotionPreference } from "./motion-provider";

export type ThemeName = "light";
export type DesignTokens = { [key: `--cobalt-${string}`]: string | number };
const ThemeContext = createContext<ThemeName>("light");
const TokensContext = createContext<DesignTokens>({});
export const useDesignTheme = () => useContext(ThemeContext);
export const useDesignTokens = () => useContext(TokensContext);

export function DesignThemeProvider({
  theme,
  children,
  motion = "inherit",
  tokens,
}: {
  theme: ThemeName;
  children: ReactNode;
  motion?: MotionPreference;
  tokens?: DesignTokens;
}) {
  const inheritedTokens = useDesignTokens();
  const mergedTokens = { ...inheritedTokens, ...tokens };

  return (
    <ThemeContext.Provider value={theme}>
      <TokensContext.Provider value={mergedTokens}>
        <MotionProvider motion={motion}>
          <div className="cobalt-root" data-cobalt-theme={theme} style={mergedTokens}>
            {children}
          </div>
        </MotionProvider>
      </TokensContext.Provider>
    </ThemeContext.Provider>
  );
}

// 既存と同じく、テーマ指定なしで読み込むための入口を用意する。
export function ThemeProvider({
  children,
  motion,
  tokens,
}: {
  children: ReactNode;
  motion?: MotionPreference;
  tokens?: DesignTokens;
}) {
  return (
    <DesignThemeProvider theme="light" motion={motion} tokens={tokens}>
      {children}
    </DesignThemeProvider>
  );
}

import { createContext, useContext, useSyncExternalStore, type ReactNode } from "react";

export type MotionPreference = "inherit" | "on" | "off";
const MotionContext = createContext<"on" | "off">("on");
const reducedMotionQuery = "(prefers-reduced-motion: reduce)";

function subscribeReducedMotion(notify: () => void) {
  const query = window.matchMedia(reducedMotionQuery);
  query.addEventListener("change", notify);
  return () => query.removeEventListener("change", notify);
}

function getReducedMotion() {
  return window.matchMedia(reducedMotionQuery).matches;
}

function useMotionPreference(motion: MotionPreference) {
  const inherited = useContext(MotionContext);
  return motion === "inherit" ? inherited : motion;
}

// 部品の指定を親から継承し、OSが動きを減らす設定ならOFFにする。
export function useDesignMotion(motion: MotionPreference = "inherit"): "on" | "off" {
  const preference = useMotionPreference(motion);
  const reduced = useSyncExternalStore(subscribeReducedMotion, getReducedMotion, () => false);
  return reduced ? "off" : preference;
}

// DOM要素を増やさずに設定を渡す。子の部品ではON/OFFを上書きできる。
export function MotionProvider({
  motion = "inherit",
  children,
}: {
  motion?: MotionPreference;
  children: ReactNode;
}) {
  const preference = useMotionPreference(motion);
  return <MotionContext.Provider value={preference}>{children}</MotionContext.Provider>;
}

import { type ReactNode } from "react";
import { createPortal } from "react-dom";
import { DesignThemeProvider, useDesignTheme, useDesignTokens } from "./theme-provider";
import { type MotionPreference } from "./motion-provider";

// PortalではDOMの親が変わるため、テーマと上書きした色を配置先へ渡す。
export function ThemePortal({
  children,
  container,
  motion = "inherit",
}: {
  children: ReactNode;
  container?: Element | DocumentFragment | null;
  motion?: MotionPreference;
}) {
  const theme = useDesignTheme();
  const tokens = useDesignTokens();

  return createPortal(
    <DesignThemeProvider theme={theme} tokens={tokens} motion={motion}>
      {children}
    </DesignThemeProvider>,
    container ?? document.body,
  );
}

import { useCallback, useLayoutEffect, useRef, type Ref } from "react";
import { useDesignMotion, type MotionPreference } from "./motion-provider";

// React 19のcallback refの後始末とobject refの両方を維持する。
export function assignMotionRef<T>(ref: Ref<T> | undefined, element: T | null) {
  if (typeof ref === "function") return ref(element);
  if (ref) ref.current = element;
}

type Feedback =
  | "check"
  | "switch"
  | "radio"
  | "toggle"
  | "status"
  | "complete"
  | "invalid"
  | "calendar"
  | "ready"
  | "message";

// CSSの状態遷移と競合しないよう、補助動作には独立したscale/translate/rotateを使う。
// 値と曲線の正本はstyles/registry.json。未読込時は動きを加えない。
function playFeedback(
  element: HTMLElement,
  feedback: Feedback,
  animate: (target: Element, frames: Keyframe[], duration: string) => void,
) {
  const state = element.getAttribute("data-state");
  if (feedback === "check") {
    if (state === "unchecked") return;
    const indicator = element.querySelector(".cobalt-checkbox-indicator");
    if (indicator)
      animate(
        indicator,
        [{ scale: ".5" }, { scale: "1.16", offset: 0.65 }, { scale: "1" }],
        "feedback",
      );
    const path = element.querySelector<SVGGeometryElement>(".cobalt-checkbox-check path");
    if (state === "checked" && path) {
      const length = path.getTotalLength();
      animate(
        path,
        [
          { strokeDasharray: `${length}`, strokeDashoffset: length },
          { strokeDasharray: `${length}`, strokeDashoffset: 0 },
        ],
        "selection",
      );
    }
  } else if (feedback === "switch") {
    const thumb = element.querySelector(".cobalt-switch-thumb");
    if (thumb)
      animate(
        thumb,
        [
          { scale: "1 1" },
          { scale: ".84 1.12", offset: 0.25 },
          { scale: "1.1 .95", offset: 0.65 },
          { scale: "1 1" },
        ],
        "feedback",
      );
  } else if (feedback === "radio") {
    const indicator = element.querySelector(".cobalt-radio-indicator");
    if (state === "checked" && indicator)
      animate(
        indicator,
        [{ scale: ".35" }, { scale: "1.2", offset: 0.65 }, { scale: "1" }],
        "feedback",
      );
  } else if (feedback === "toggle") {
    if (state !== "on" && element.getAttribute("aria-current") !== "page") return;
    const icon = element.querySelector("svg");
    animate(
      icon ?? element,
      [{ scale: ".88" }, { scale: "1.08", offset: 0.65 }, { scale: "1" }],
      "feedback",
    );
  } else if (feedback === "status") {
    const variant = element.getAttribute("data-variant");
    const mark = element.querySelector(".cobalt-badge-mark");
    if (variant === "destructive" || (!mark && variant !== "success")) {
      animate(element, [{ opacity: 0.65 }, { opacity: 1 }], "selection");
      return;
    }
    animate(
      mark ?? element,
      [
        { scale: mark ? ".7" : ".98", opacity: 0.5 },
        { scale: mark ? "1.12" : "1.01", opacity: 1, offset: 0.65 },
        { scale: "1", opacity: 1 },
      ],
      "celebrate",
    );
  } else if (feedback === "complete") {
    const indicator = element.querySelector(".cobalt-progress-indicator");
    if (state === "complete" && indicator)
      animate(indicator, [{ opacity: 0.55 }, { opacity: 1 }], "celebrate");
  } else if (feedback === "invalid") {
    if (element.getAttribute("aria-invalid") === "true")
      animate(
        element,
        [
          { translate: "0" },
          { translate: "-2px 0", offset: 0.25 },
          { translate: "2px 0", offset: 0.5 },
          { translate: "-1px 0", offset: 0.75 },
          { translate: "0" },
        ],
        "selection",
      );
  } else if (feedback === "calendar") {
    if (
      element.getAttribute("data-selected-single") === "true" ||
      element.getAttribute("data-range-end") === "true"
    )
      animate(
        element,
        [{ scale: ".86" }, { scale: "1.06", offset: 0.7 }, { scale: "1" }],
        "feedback",
      );
  } else if (feedback === "ready" && state === "ready") {
    animate(element, [{ opacity: 0.5 }, { opacity: 1 }], "entry");
  } else if (feedback === "message" && element.getAttribute("data-status") === "sent") {
    animate(
      element,
      [
        { translate: "0 2px", opacity: 0.8 },
        { translate: "0 0", opacity: 1 },
      ],
      "menu",
    );
  }
}

export function useMotionFeedback<T extends HTMLElement>({
  motion = "inherit",
  ref: forwardedRef,
  feedback,
}: {
  motion?: MotionPreference;
  ref?: Ref<T>;
  feedback: Feedback;
}) {
  const effective = useDesignMotion(motion);
  const current = useRef({ effective, feedback });
  const animations = useRef(new Map<Element, Set<Animation>>());

  const cancel = useCallback(() => {
    for (const group of animations.current.values())
      for (const animation of group) animation.cancel();
    animations.current.clear();
  }, []);

  useLayoutEffect(() => {
    current.current = { effective, feedback };
    if (effective === "off") cancel();
  }, [effective, feedback, cancel]);

  const ref = useCallback(
    (element: T | null) => {
      const release = assignMotionRef(forwardedRef, element);
      if (!element) return;

      const attributes =
        feedback === "status"
          ? ["data-variant"]
          : feedback === "invalid"
            ? ["aria-invalid"]
            : feedback === "toggle"
              ? ["data-state", "aria-current"]
              : feedback === "calendar"
                ? ["data-selected-single", "data-range-end"]
                : feedback === "message"
                  ? ["data-status"]
                  : ["data-state"];

      const values = attributes.map((attribute) => element.getAttribute(attribute));

      const observer = new MutationObserver(() => {
        let changed = false;
        attributes.forEach((attribute, index) => {
          const value = element.getAttribute(attribute);
          if (values[index] !== value) changed = true;
          values[index] = value;
        });
        // 初回描画やON/OFFの変更だけでは再生しない。
        if (
          !changed ||
          current.current.effective !== "on" ||
          element.matches(":disabled, [aria-disabled=true]")
        )
          return;
        cancel();
        const style = getComputedStyle(element);
        playFeedback(element, current.current.feedback, (target, frames, duration) => {
          const milliseconds = parseFloat(style.getPropertyValue(`--cobalt-duration-${duration}`));
          const easing = style.getPropertyValue("--cobalt-ease-out").trim();
          if (!milliseconds || !easing || typeof target.animate !== "function") return;
          const animation = target.animate(frames, { duration: milliseconds, easing });
          const group = animations.current.get(target) ?? new Set<Animation>();
          group.add(animation);
          animations.current.set(target, group);
          void animation.finished.then(
            () => group.delete(animation),
            () => group.delete(animation),
          );
        });
      });

      observer.observe(element, { attributes: true, attributeFilter: attributes });
      return () => {
        observer.disconnect();
        cancel();
        if (typeof release === "function") release();
        else assignMotionRef(forwardedRef, null);
      };
    },
    [forwardedRef, feedback, cancel],
  );

  return { ref, effective };
}

// Radixが計測中にanimationを止める部品でも、位置確定後に一度だけ登場させる。
// 完了・中断で印を外すため、ONへの復帰だけでは再生しない。
export function useMotionEntry<T extends HTMLElement>(forwardedRef?: Ref<T>) {
  const effective = useDesignMotion();
  const preference = useRef(effective);
  const root = useRef<T | null>(null);
  useLayoutEffect(() => {
    preference.current = effective;
    if (effective === "off") root.current?.removeAttribute("data-cobalt-entry");
  }, [effective]);

  const ref = useCallback(
    (element: T | null) => {
      const release = assignMotionRef(forwardedRef, element);
      root.current = element;
      if (!element) return;

      const begin = () => {
        if (
          preference.current === "on" &&
          element.isConnected &&
          element.dataset.state !== "closed"
        )
          element.dataset.cobaltEntry = "enter";
      };

      let state = element.dataset.state;

      const observer = new MutationObserver(() => {
        const next = element.dataset.state;
        if (next === state) return;
        state = next;
        if (next === "closed") element.removeAttribute("data-cobalt-entry");
        else begin();
      });

      observer.observe(element, { attributes: true, attributeFilter: ["data-state"] });

      const finish = (event: AnimationEvent) => {
        if (event.target === element && event.animationName.startsWith("cobalt-"))
          element.removeAttribute("data-cobalt-entry");
      };

      element.addEventListener("animationend", finish);
      begin();
      return () => {
        observer.disconnect();
        element.removeEventListener("animationend", finish);
        element.removeAttribute("data-cobalt-entry");
        if (typeof release === "function") release();
        else assignMotionRef(forwardedRef, null);
      };
    },
    [forwardedRef],
  );

  return { ref, effective };
}

import { useCallback, useLayoutEffect, useRef, type Ref } from "react";
import { useDesignMotion, type MotionPreference } from "./motion-provider";
import { assignMotionRef } from "./motion-feedback";

function timing(element: Element, token: string) {
  const style = getComputedStyle(element);
  return {
    duration: parseFloat(style.getPropertyValue(`--cobalt-duration-${token}`)) || 0,
    easing: style.getPropertyValue("--cobalt-ease-out").trim() || "ease-out",
  };
}

// 選択位置を示す面だけを移動し、タブの文字やクリック領域は動かさない。
export function useSelectionIndicator(ref: Ref<HTMLDivElement> | undefined) {
  const effective = useDesignMotion();
  const preference = useRef(effective);
  const stop = useRef<() => void>(() => {});
  useLayoutEffect(() => {
    preference.current = effective;
    if (effective === "off") stop.current();
  }, [effective]);

  const callback = useCallback(
    (list: HTMLDivElement | null) => {
      const release = assignMotionRef(ref, list);
      if (!list) return;
      const marker = list.querySelector<HTMLElement>(".cobalt-tabs-indicator");
      if (!marker)
        return () => {
          if (typeof release === "function") release();
          else assignMotionRef(ref, null);
        };
      let previous: { left: number; top: number; width: number; height: number } | undefined;
      let selected: Element | null = null;
      let animation: Animation | undefined;
      stop.current = () => animation?.cancel();

      const update = () => {
        const active = list.querySelector<HTMLElement>('[role="tab"][data-state="active"]');
        if (!active) {
          list.removeAttribute("data-cobalt-indicator");
          return;
        }
        const bounds = list.getBoundingClientRect();
        const target = active.getBoundingClientRect();
        const line = list.dataset.variant === "line";

        const vertical =
          list.closest('[data-slot="tabs"]')?.getAttribute("data-orientation") === "vertical";

        const next = {
          left:
            target.left -
            bounds.left -
            list.clientLeft +
            (line ? (vertical ? target.width - 2 : 8) : 0),
          top:
            target.top -
            bounds.top -
            list.clientTop +
            (line ? (vertical ? 8 : target.height - 2) : 0),
          width: line ? (vertical ? 3 : target.width - 16) : target.width,
          height: line ? (vertical ? target.height - 16 : 3) : target.height,
        };

        if (
          selected === active &&
          previous &&
          previous.left === next.left &&
          previous.top === next.top &&
          previous.width === next.width &&
          previous.height === next.height
        )
          return;
        const visible = animation?.playState === "running" ? marker.getBoundingClientRect() : null;

        const from = visible
          ? {
              left: visible.left - bounds.left - list.clientLeft,
              top: visible.top - bounds.top - list.clientTop,
              width: visible.width,
              height: visible.height,
            }
          : previous;

        animation?.cancel();
        Object.assign(marker.style, {
          left: `${next.left}px`,
          top: `${next.top}px`,
          width: `${next.width}px`,
          height: `${next.height}px`,
        });
        list.dataset.cobaltIndicator = "ready";
        if (from && selected !== active && preference.current === "on") {
          const options = timing(list, "expand");
          if (options.duration)
            animation = marker.animate(
              [
                {
                  left: `${from.left}px`,
                  top: `${from.top}px`,
                  width: `${from.width}px`,
                  height: `${from.height}px`,
                },
                {
                  left: `${next.left}px`,
                  top: `${next.top}px`,
                  width: `${next.width}px`,
                  height: `${next.height}px`,
                },
              ],
              options,
            );
        }
        previous = next;
        selected = active;
      };

      const observer = new MutationObserver(update);
      observer.observe(list, {
        subtree: true,
        attributes: true,
        attributeFilter: ["data-state", "data-orientation", "data-variant"],
        childList: true,
      });
      const resize = new ResizeObserver(update);
      resize.observe(list);
      for (const tab of list.querySelectorAll('[role="tab"]')) resize.observe(tab);
      update();
      return () => {
        observer.disconnect();
        resize.disconnect();
        animation?.cancel();
        if (typeof release === "function") release();
        else assignMotionRef(ref, null);
      };
    },
    [ref],
  );

  return { ref: callback, effective };
}

// 検索・並べ替え後の位置関係を示す。初回表示やONへの復帰だけでは再生しない。
export function useListMotion<T extends HTMLElement>(
  motion: MotionPreference,
  change: string,
  selector: string,
) {
  const effective = useDesignMotion(motion);
  const ref = useRef<T>(null);
  const previous = useRef<{ change: string; positions: Map<Element, DOMRect> } | null>(null);
  const animations = useRef<Animation[]>([]);
  useLayoutEffect(() => {
    const root = ref.current;
    if (!root) return;
    for (const animation of animations.current) animation.cancel();
    animations.current = [];
    const elements = Array.from(root.querySelectorAll(selector));

    const positions = new Map(
      elements.map((element) => [element, element.getBoundingClientRect()]),
    );

    const old = previous.current;
    previous.current = { change, positions };
    if (effective !== "on" || !old || old.change === change) return;
    const options = timing(root, "expand");
    if (!options.duration) return;
    elements.forEach((element, index) => {
      const from = old.positions.get(element);
      const to = positions.get(element)!;
      const x = from ? from.left - to.left : 0;
      const y = from ? from.top - to.top : 6;
      if (from && Math.abs(x) < 1 && Math.abs(y) < 1) return;
      animations.current.push(
        element.animate(
          [
            { translate: `${x}px ${y}px`, opacity: from ? 1 : 0 },
            { translate: "0 0", opacity: 1 },
          ],
          { ...options, delay: from ? 0 : Math.min(index, 4) * 20, fill: "backwards" },
        ),
      );
    });
  }, [effective, change, selector]);
  useLayoutEffect(
    () => () => {
      for (const animation of animations.current) animation.cancel();
    },
    [],
  );
  return ref;
}

// ステップの進退など、既存の内容が別の内容へ切り替わったときだけ動かす。
export function useStepMotion(motion: MotionPreference, step: number) {
  const effective = useDesignMotion(motion);
  const ref = useRef<HTMLElement>(null);
  const previous = useRef(step);
  const animation = useRef<Animation | undefined>(undefined);
  useLayoutEffect(() => {
    const old = previous.current;
    previous.current = step;
    animation.current?.cancel();
    if (old === step || effective !== "on" || !ref.current) return;
    const options = timing(ref.current, "expand");

    const distance =
      parseFloat(getComputedStyle(ref.current).getPropertyValue("--cobalt-motion-distance")) || 12;

    if (options.duration)
      animation.current = ref.current.animate(
        [
          { translate: `${step > old ? distance : -distance}px 0`, opacity: 0 },
          { translate: "0 0", opacity: 1 },
        ],
        options,
      );
  }, [step, effective]);
  useLayoutEffect(() => () => animation.current?.cancel(), []);
  return ref;
}
